Ot(a,b){return a+" \u0915\u094b \u0928\u0939\u0940\u0902 \u0939\u091f\u093e\u092f\u093e \u091c\u093e \u0938\u0915\u093e: "+b},
gFx(){return"\u0939\u091f\u093e\u090f\u0902"},
gOl(){return"\u0915\u094b\u0908 \u092b\u093c\u094b\u0928 \u0928\u0939\u0940\u0902"},
gOy(){return"\u092a\u093f\u0928 \u0930\u0940\u0938\u0947\u091f \u0915\u0930\u0947\u0902"},
gOe(){return"\u090f\u0921\u092e\u093f\u0928 \u090f\u0915\u094d\u0938\u0947\u0938"},
