gOi(){return"\u091f\u0940\u092e \u0938\u0926\u0938\u094d\u092f \u0938\u0902\u092a\u093e\u0926\u093f\u0924 \u0915\u0930\u0947\u0902"},
gOo(){return"\u092b\u093c\u094b\u0928 (\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915)"},
gOH(){return"\u092a\u094d\u0930\u093e\u0930\u0902\u092d\u093f\u0915 \u092a\u093f\u0928 (4+ \u0905\u0902\u0915)"},
gOG(){return"\u0935\u0947 \u0938\u093e\u0907\u0928 \u0907\u0928 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0907\u0938\u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0947\u0902\u0917\u0947 \u2014 \u0907\u0938\u0915\u0947 \u092c\u093f\u0928\u093e \u0909\u0928\u094d\u0939\u0947\u0902 \u092c\u0928\u093e\u092f\u093e \u0928\u0939\u0940\u0902 \u091c\u093e \u0938\u0915\u0924\u093e\u0964"},
gOB(){return"\u092d\u0942\u092e\u093f\u0915\u093e"},
gOF(){return"\u092c\u093f\u0915\u094d\u0930\u0940 \u091f\u0940\u092e"},
gRV(){return"\u0916\u093e\u0924\u093e \u0932\u0947\u092c\u0932"},
gHj(){return"\u092c\u0948\u0902\u0915 \u0915\u093e \u0928\u093e\u092e (\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915)"},
gHh(){return"\u0916\u093e\u0924\u093e \u0938\u0902\u0916\u094d\u092f\u093e (\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915)"},
gHl(){return"IBAN (\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915)"},
gRW(){return'\u0916\u093e\u0924\u093e \u0932\u0947\u092c\u0932 (\u091c\u0948\u0938\u0947 "ADCB Current")'},
gS6(){return"\u092a\u094d\u0930\u093e\u0930\u0902\u092d\u093f\u0915 \u0936\u0947\u0937"},
ga12(){return'\u091c\u0948\u0938\u0947 "\u092b\u094d\u0930\u0902\u091f \u0921\u0947\u0938\u094d\u0915 \u092b\u094d\u0932\u094b\u091f"'},
ga1_(){return"\u0905\u092d\u093f\u0930\u0915\u094d\u0937\u0915 (\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915)"},
ga18(){return"\u092a\u094d\u0930\u093e\u0930\u0902\u092d\u093f\u0915 \u092b\u094d\u0932\u094b\u091f"},
gKH(){return"\u0930\u093e\u0936\u093f"},
ga0X(){return"\u0936\u094d\u0930\u0947\u0923\u0940"},
ga17(){return"\u0928\u094b\u091f (\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915)"},
gVY(){return"\u092a\u0941\u0937\u094d\u091f\u093f \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f RESET \u091f\u093e\u0907\u092a \u0915\u0930\u0947\u0902"},
gVR(){return"\u0938\u092c \u0915\u0941\u091b \u092e\u093f\u091f\u093e\u090f\u0902"},
VX(a){return"\u0930\u0940\u0938\u0947\u091f \u0935\u093f\u092b\u0932: "+a},
gVV(){return"\u0938\u092d\u0940 \u0921\u0947\u091f\u093e \u0930\u0940\u0938\u0947\u091f \u0915\u0930\u0947\u0902?"},
gVS(){return"\u092f\u0939 \u0938\u091a\u092e\u0941\u091a \u0935\u0939 \u0938\u092c \u0915\u0941\u091b \u092e\u093f\u091f\u093e \u0926\u0947\u0924\u093e \u0939\u0948 \u091c\u094b \u0935\u094d\u092f\u0935\u0938\u093e\u092f \u0928\u0947 \u0915\u092d\u0940 \u0926\u0930\u094d\u091c \u0915\u093f\u092f\u093e \u092f\u093e \u0906\u092f\u093e\u0924 \u0915\u093f\u092f\u093e \u0939\u0948: \u0939\u0930 \u0917\u094d\u0930\u093e\u0939\u0915, \u0906\u092a\u0942\u0930\u094d\u0924\u093f\u0915\u0930\u094d\u0924\u093e, \u0906\u0907\u091f\u092e, \u091a\u093e\u0932\u093e\u0928, \u0916\u0930\u0940\u0926, \u0928\u094b\u091f, \u091a\u0947\u0915, \u0921\u093f\u0932\u0940\u0935\u0930\u0940, \u0935\u093e\u0909\u091a\u0930, \u0932\u0947\u091c\u0930 \u092a\u094d\u0930\u0935\u093f\u0937\u094d\u091f\u093f, \u0938\u094d\u091f\u0949\u0915 \u092e\u0942\u0935\u092e\u0947\u0902\u091f, \u092c\u0948\u0902\u0915 \u0916\u093e\u0924\u093e, \u0915\u0930\u094d\u092e\u091a\u093e\u0930\u0940, \u0914\u0930 \u0911\u0921\u093f\u091f \u0932\u0949\u0917\u0964\n\n\u0915\u0947\u0935\u0932 \u0936\u093e\u0916\u093e(\u090f\u0902), \u0915\u0902\u092a\u0928\u0940 \u092a\u094d\u0930\u094b\u092b\u093c\u093e\u0907\u0932, \u0914\u0930 \u0938\u094d\u091f\u093e\u092b \u0932\u0949\u0917\u093f\u0928 \u092c\u091a\u0924\u0947 \u0939\u0948\u0902 \u2014 \u0924\u093e\u0915\u093f \u0906\u092a \u0905\u092d\u0940 \u092d\u0940 \u0910\u092a \u092e\u0947\u0902 \u0935\u093e\u092a\u0938 \u0906 \u0938\u0915\u0947\u0902\u0964 \u092c\u093e\u0915\u0940 \u0938\u092c \u0915\u0941\u091b \u0916\u093e\u0932\u0940 \u0935\u093e\u092a\u0938 \u0906\u0924\u093e \u0939\u0948, \u092c\u093f\u0932\u094d\u0915\u0941\u0932 \u090f\u0915 \u092c\u093f\u0932\u094d\u0915\u0941\u0932 \u0928\u0908 \u0915\u0902\u092a\u0928\u0940 \u0915\u0940 \u0924\u0930\u0939\u0964\n\n\u0907\u0938\u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0926\u094b\u092c\u093e\u0930\u093e \u091a\u0932\u093e\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u0921\u0941\u092a\u094d\u0932\u093f\u0915\u0947\u091f \u092f\u093e \u092c\u093f\u0917\u0921\u093c\u0947 \u0939\u0941\u090f \u0906\u092f\u093e\u0924 \u0915\u094b \u0938\u093e\u092b \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u0947 \u092a\u0942\u0930\u094d\u0935\u0935\u0924 \u0928\u0939\u0940\u0902 \u0915\u093f\u092f\u093e \u091c\u093e \u0938\u0915\u0924\u093e\u0964"},
gVQ(){return"\u0939\u0930 \u0935\u094d\u092f\u093e\u0935\u0938\u093e\u092f\u093f\u0915 \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u092e\u093f\u091f\u093e \u0926\u093f\u092f\u093e \u0917\u092f\u093e \u0939\u0948 \u2014 \u0915\u0902\u092a\u0928\u0940 \u0916\u093e\u0932\u0940 \u0939\u094b \u0917\u0908 \u0939\u0948\u0964"},
gVU(){return"\u0938\u092d\u0940 \u0921\u0947\u091f\u093e \u0930\u0940\u0938\u0947\u091f \u0915\u0930\u0947\u0902"},
gVT(){return"\u0939\u0930 \u0917\u094d\u0930\u093e\u0939\u0915, \u0906\u092a\u0942\u0930\u094d\u0924\u093f\u0915\u0930\u094d\u0924\u093e, \u0906\u0907\u091f\u092e, \u0914\u0930 \u0932\u0947\u0928\u0926\u0947\u0928 \u2014 \u090f\u0915 \u092c\u093f\u0932\u094d\u0915\u0941\u0932 \u0928\u0908 \u0915\u0902\u092a\u0928\u0940 \u092e\u0947\u0902 \u0935\u093e\u092a\u0938 \u092e\u093f\u091f\u093e \u0926\u093f\u092f\u093e \u0917\u092f\u093e\u0964 \u0915\u0947\u0935\u0932 \u0936\u093e\u0916\u093e(\u090f\u0902), \u0915\u0902\u092a\u0928\u0940 \u092a\u094d\u0930\u094b\u092b\u093c\u093e\u0907\u0932, \u0914\u0930 \u0938\u094d\u091f\u093e\u092b \u0932\u0949\u0917\u093f\u0928 \u092c\u091a\u0924\u0947 \u0939\u0948\u0902\u0964 \u0907\u0938\u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0926\u094b\u092c\u093e\u0930\u093e \u091a\u0932\u093e\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u0921\u0941\u092a\u094d\u0932\u093f\u0915\u0947\u091f \u092f\u093e \u092c\u093f\u0917\u0921\u093c\u0947 \u0939\u0941\u090f \u0906\u092f\u093e\u0924 \u0915\u094b \u0938\u093e\u092b \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u0930\u0947\u0902\u0964"},
gVW(){return"\u0930\u0940\u0938\u0947\u091f"},
gRS(){return"\u0915\u0947\u0935\u0932 \u0938\u094d\u0935\u093e\u092e\u0940 \u0939\u0940 \u0915\u0902\u092a\u0928\u0940 \u0915\u0947 \u0921\u0947\u091f\u093e \u0915\u093e \u092c\u0948\u0915\u0905\u092a \u092f\u093e \u092a\u0941\u0928\u0930\u094d\u0938\u094d\u0925\u093e\u092a\u0928\u093e \u0915\u0930 \u0938\u0915\u0924\u093e \u0939\u0948\u0964"},
gMW(){return"SMTP \u0939\u094b\u0938\u094d\u091f"},
